/*
 * As peças do tópico de mensagem do Discourse que o flarum/messages não tem:
 *
 * - o mapa da mensagem: "N visualizações" e a linha de participantes em
 *   pílulas (o grupo, as pessoas — a minha com ✕ para sair — e o "+" para
 *   convidar);
 * - o modal "Convidar";
 * - a linha do tempo da direita (datas, "n/n", responder e o sino);
 * - o controle de notificação da mensagem (Acompanhando, Monitorando, Normal,
 *   Silenciado(a)) com o motivo embaixo.
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import FormModal from 'flarum/common/components/FormModal';
import Avatar from 'flarum/common/components/Avatar';
import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import DetailedDropdownItem from 'flarum/common/components/DetailedDropdownItem';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import Tooltip from 'flarum/common/components/Tooltip';
import Stream from 'flarum/common/utils/Stream';
import classList from 'flarum/common/utils/classList';
import RecipientChooser from './RecipientChooser';
import { leaveDialog } from './actions';
import { shortDate } from '../../utils/dates';
import humanTime from 'flarum/common/helpers/humanTime';
import { t } from '../../utils/settings';
import { bellIcon } from '../../utils/bells';
import { boxesOn, dialogViews, groupLabel, messageCount, messageGroup, participants, staffGroups } from './util';

// ---------------------------------------------------------------------
// Mapa
// ---------------------------------------------------------------------

export function DialogMap(dialog) {
  const users = participants(dialog);
  const me = app.session.user;
  const views = dialogViews(dialog);
  const groups = staffGroups(dialog).filter(() => !!dialog.attribute('canelaGroupId'));
  return m("section", {
    className: "CanelaTopicMap CanelaTopicMap--op CanelaDialogMap",
    "aria-label": t('messages.topic.map_label')
  }, views !== null ? m("div", {
    className: "CanelaDialogMap-contents"
  }, m("span", {
    className: "CanelaDialogMap-views"
  }, t('messages.topic.views', {
    count: views
  }))) : null, m("div", {
    className: "CanelaDialogMap-pm"
  }, m("div", {
    className: "participants"
  }, groups.map(group => m("div", {
    className: "user group",
    "data-id": group.id()
  }, m("span", {
    className: "group-link"
  }, m(Icon, {
    name: "fas fa-user-group"
  }), m("span", {
    className: "group-name"
  }, groupLabel(group))))), users.map(user => m("div", {
    className: "user",
    "data-id": user.id()
  }, m(Link, {
    href: app.route.user(user),
    className: "user-link",
    title: user.username()
  }, m(Avatar, {
    user: user,
    title: user.displayName()
  }), m("span", {
    className: "username"
  }, user.username())), boxesOn() && me && (user === me || dialog.attribute('canelaCanRemove')) ? m(Tooltip, {
    text: user === me ? t('messages.topic.leave') : t('messages.topic.remove_user')
  }, m(Button, {
    className: "Button Button--icon remove-invited",
    icon: "fas fa-xmark",
    "aria-label": user === me ? t('messages.topic.leave') : t('messages.topic.remove_user'),
    onclick: () => user === me ? leaveDialog(dialog) : removeParticipant(dialog, user)
  })) : null)), boxesOn() && dialog.canSendMessage() !== false ? m(Tooltip, {
    text: t('messages.invite.title')
  }, m(Button, {
    className: "Button Button--icon add-participant-btn",
    icon: "fas fa-plus",
    "aria-label": t('messages.invite.title'),
    onclick: () => app.modal.show(InviteModal, {
      dialog
    })
  })) : null)));
}

/** "Tem certeza de que quer remover @fulano desta mensagem?" */
function removeParticipant(dialog, user) {
  if (!confirm(t('messages.topic.remove_confirm', {
    name: user.username()
  }))) return;
  app.request({
    method: 'DELETE',
    url: `${app.forum.attribute('apiUrl')}/dialogs/${dialog.id()}/canela-membership`,
    params: {
      userId: user.id()
    }
  }).then(() => app.store.find('dialogs', dialog.id(), {
    include: 'users.groups'
  })).then(() => m.redraw()).catch(() => {});
}

// ---------------------------------------------------------------------
// Posts de ação pequena (convidou / removeu / saiu)
// ---------------------------------------------------------------------

export function dialogEvents(dialog) {
  const events = dialog.attribute('canelaEvents');
  return Array.isArray(events) ? events : [];
}
const EVENT_ICONS = {
  invited_user: 'fas fa-circle-plus',
  invited_group: 'fas fa-circle-plus',
  removed_user: 'fas fa-circle-minus',
  user_left: 'fas fa-circle-minus'
};

/**
 * A small action do Discourse (`.small-action`): o ícone na coluna do
 * avatar, o avatar de quem fez e "Convidou @fulano há 2 dias".
 */
export function DialogEventView(event) {
  const actor = event.actorId ? app.store.getById('users', event.actorId) : null;
  const target = event.targetUserId ? app.store.getById('users', event.targetUserId) : null;
  const when = humanTime(new Date(event.createdAt));
  const who = event.type === 'invited_group' ? m("span", {
    className: "CanelaDialogEvent-who"
  }, event.groupName) : target ? m(Link, {
    href: app.route.user(target),
    className: "CanelaDialogEvent-who"
  }, "@", target.username()) : m("span", {
    className: "CanelaDialogEvent-who"
  }, "@", event.targetUsername || event.actorUsername);
  return m("div", {
    className: `CanelaDialogEvent CanelaDialogEvent--${event.type}`,
    key: `event-${event.id}`
  }, m("span", {
    className: "CanelaDialogEvent-icon"
  }, m(Icon, {
    name: EVENT_ICONS[event.type] || 'fas fa-circle-info'
  })), m("span", {
    className: "CanelaDialogEvent-avatar"
  }, actor ? m(Avatar, {
    user: actor,
    title: actor.username()
  }) : null), m("span", {
    className: "CanelaDialogEvent-text"
  }, app.translator.trans(`ramon-canela.forum.messages.events.${event.type}`, {
    who,
    when
  })));
}

// ---------------------------------------------------------------------
// Convidar
// ---------------------------------------------------------------------

/**
 * "Convidar" (`invite` do tópico de mensagem): o mesmo seletor de pessoas e
 * grupos do composer e "✉ Enviar convite", desabilitado até alguém ser
 * escolhido.
 */
export class InviteModal extends FormModal {
  users = Stream([]);
  group = Stream(null);
  className() {
    return 'Modal--small CanelaDialogInviteModal';
  }
  title() {
    return t('messages.invite.title');
  }
  content() {
    const ready = this.users().length > 0 || !!this.group();
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "CanelaDialogInviteModal-help"
    }, t('messages.invite.help')), m("div", {
      className: "Form-group CanelaDialogInviteModal-field"
    }, m(RecipientChooser, {
      className: "CanelaDialogInviteModal-chooser",
      recipients: this.users,
      group: messageGroup() ? this.group : undefined,
      max: 20,
      placeholder: t('messages.invite.placeholder')
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary CanelaDialogInviteModal-submit",
      type: "submit",
      icon: "fas fa-envelope",
      loading: this.loading,
      disabled: !ready
    }, t('messages.invite.submit'))));
  }
  onsubmit(e) {
    e.preventDefault();
    const dialog = this.attrs.dialog;
    this.loading = true;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/dialogs/${dialog.id()}/canela-invite`,
      body: {
        userIds: this.users().map(user => Number(user.id())),
        groupId: this.group() || undefined
      },
      // O erro (grupo que não recebe mensagens, limite de destinatários)
      // aparece dentro do modal, como no Discourse, e não atrás dele.
      errorHandler: this.onerror.bind(this)
    })
    // Recarrega a conversa: o grupo entra no mapa e o post de ação
    // "Convidou Admins" aparece na linha da conversa.
    .then(() => app.store.find('dialogs', dialog.id(), {
      include: 'users.groups'
    })).then(() => {
      app.alerts.show({
        type: 'success'
      }, t(this.group() && !this.users().length ? 'messages.invite.success_group' : 'messages.invite.success'));
      this.hide();
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}

// ---------------------------------------------------------------------
// Linha do tempo
// ---------------------------------------------------------------------

/**
 * A linha do tempo do tópico, no tamanho de uma mensagem: a data da primeira
 * no topo, a trilha com "n/n" e a data da última, a data embaixo e os botões
 * redondos de responder e de notificação.
 */
export class DialogTimeline extends Component {
  view() {
    const dialog = this.attrs.dialog;
    const count = Math.max(1, messageCount(dialog));
    const first = dialog.createdAt();
    const last = dialog.lastMessageAt() || first;
    return m("div", {
      className: "CanelaDialogTimeline",
      "aria-hidden": "false"
    }, m("div", {
      className: "CanelaDialogTimeline-date CanelaDialogTimeline-date--start"
    }, first ? shortDate(first) : ''), m("div", {
      className: "CanelaDialogTimeline-track"
    }, m("div", {
      className: "CanelaDialogTimeline-handle"
    }, m("strong", {
      className: "CanelaDialogTimeline-count"
    }, count, "/", count), m("span", {
      className: "CanelaDialogTimeline-handleDate"
    }, last ? shortDate(last) : ''))), m("div", {
      className: "CanelaDialogTimeline-date CanelaDialogTimeline-date--end"
    }, last ? shortDate(last) : ''), m("div", {
      className: "CanelaDialogTimeline-controls"
    }, dialog.canSendMessage() !== false ? m(Tooltip, {
      text: t('messages.topic.reply')
    }, m(Button, {
      className: "Button Button--icon CanelaDialogTimeline-reply",
      icon: "fas fa-reply",
      "aria-label": t('messages.topic.reply'),
      onclick: () => this.attrs.onreply()
    })) : null, m(DialogNotifications, {
      dialog: dialog,
      compact: true
    })));
  }
}

// ---------------------------------------------------------------------
// Notificações
// ---------------------------------------------------------------------

/** Os níveis do Discourse para mensagens (`watching_pm` … `muted_pm`). */
const LEVELS = [{
  value: 3,
  key: 'watching',
  get icon() {
    return bellIcon('watching');
  }
}, {
  value: 2,
  key: 'tracking',
  get icon() {
    return bellIcon('tracking');
  }
}, {
  value: 1,
  key: 'regular',
  icon: 'far fa-bell'
}, {
  value: 0,
  key: 'muted',
  icon: 'fas fa-bell-slash'
}];
function currentLevel(dialog) {
  const value = dialog.attribute('canelaNotificationLevel');
  return LEVELS.find(level => level.value === (typeof value === 'number' ? value : 3)) || LEVELS[0];
}

/** Com o backend e a migration de grupos: o nível vem no diálogo. */
export function levelsOn(dialog) {
  return boxesOn() && typeof dialog.attribute('canelaNotificationLevel') === 'number';
}
export class DialogNotifications extends Component {
  view() {
    const dialog = this.attrs.dialog;
    if (!levelsOn(dialog)) return null;
    const current = currentLevel(dialog);
    const compact = !!this.attrs.compact;
    return m(Dropdown, {
      className: classList('CanelaNotifications', `CanelaNotifications--${current.key === 'watching' ? 'watching' : current.key === 'muted' ? 'muted' : 'normal'}`, {
        'CanelaNotifications--compact': compact
      }),
      buttonClassName: classList('Button CanelaNotifications-button', {
        'Button--icon': compact
      }),
      menuClassName: "CanelaNotifications-menu",
      icon: current.icon,
      noStyleOverride: true,
      label: compact ? '' : t(`messages.notifications.${current.key}`),
      caretIcon: compact ? '' : 'fas fa-caret-down',
      accessibleToggleLabel: t(`messages.notifications.${current.key}`),
      tooltip: compact ? t(`messages.notifications.${current.key}`) : undefined
    }, LEVELS.map(level => m(DetailedDropdownItem, {
      icon: m(Icon, {
        name: level.icon,
        className: "Button-icon",
        noStyleOverride: true
      }),
      label: t(`messages.notifications.${level.key}`),
      description: t(`messages.notifications.${level.key}_description`),
      active: level.value === current.value,
      onclick: () => {
        if (level.value !== current.value) dialog.save({
          canelaNotificationLevel: level.value
        }).catch(() => {});
      }
    })));
  }
}

/** "Você receberá notificações porque…" — o texto ao lado do botão no rodapé. */
export function notificationReason(dialog) {
  return t(`messages.notifications.${currentLevel(dialog).key}_reason`);
}
flarum.reg.add('ramon-canela', 'forum/features/messages/conversation', { DialogMap: DialogMap,dialogEvents: dialogEvents,DialogEventView: DialogEventView,InviteModal: InviteModal,DialogTimeline: DialogTimeline,levelsOn: levelsOn,DialogNotifications: DialogNotifications,notificationReason: notificationReason, });